// Unpack items array and prepare clean OpenAI Vision payload in memory
const items = $json.items || [];
return items
  .filter(item => item && item.imageUrl && item.imageUrl.startsWith('http'))
  .map(item => {
    const rawSnippet = item.rawText || item.title || '';
    const aiPayload = {
      model: 'gpt-4o-mini',
      messages: [
        {
          role: 'system',
          content: 'You are an expert automotive digital merchandising analyst. Extract vehicle lease, finance, or purchase specials from the promotional flyer image.\n\nReturn ONLY a valid JSON object matching this schema without markdown code blocks:\n{\n  "year": 2026,\n  "make": "Hyundai",\n  "model": "Tucson",\n  "trim": null,\n  "special_type": "lease",\n  "monthly_payment": 389,\n  "term_months": 36,\n  "down_payment": 2999,\n  "apr": null,\n  "msrp": null,\n  "title": "Title of special",\n  "disclaimer": "Full legal disclaimer...",\n  "expiration_date": "2026-10-31"\n}\n\nRules:\n1. special_type must be: "lease", "finance", "cash", or "service".\n2. All numerical fields must be clean numbers without "$", "%", or commas.\n3. If a field is not stated in the image, set it to null.\n4. expiration_date must be in YYYY-MM-DD format if visible, else null.'
        },
        {
          role: 'user',
          content: [
            {
              type: 'text',
              text: `Extract all special offer details for this flyer. Existing raw snippet: ${rawSnippet}`
            },
            {
              type: 'image_url',
              image_url: {
                url: item.imageUrl
              }
            }
          ]
        }
      ],
      response_format: { type: 'json_object' },
      max_tokens: 800,
      temperature: 0.1
    };

    return {
      json: {
        ...item,
        aiPayload
      }
    };
  });

// Clean and format AI responses for all incoming items
const allAiItems = $input.all();
const originalItems = $('Split Items for Processing').all();

return allAiItems.map((aiItem, index) => {
  const originalItem = originalItems[index]?.json || {};
  const aiResponse = aiItem.json?.choices?.[0]?.message?.content || '{}';
  let parsed = {};
  try {
    parsed = JSON.parse(aiResponse);
  } catch (e) {
    const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try { parsed = JSON.parse(jsonMatch[0]); } catch {}
    }
  }

  return {
    json: {
      staging_id: originalItem.id,
      image_hash: originalItem.imageHash || null,
      auto_approve: true,
      raw_text: originalItem.rawText || '',
      extracted_data: {
        year: parsed.year || new Date().getFullYear(),
        make: parsed.make || 'Unknown',
        model: parsed.model || 'Special Offer',
        trim: parsed.trim || null,
        special_type: parsed.special_type || 'lease',
        monthly_payment: parsed.monthly_payment != null ? Number(parsed.monthly_payment) : null,
        term_months: parsed.term_months != null ? Number(parsed.term_months) : null,
        down_payment: parsed.down_payment != null ? Number(parsed.down_payment) : null,
        apr: parsed.apr != null ? Number(parsed.apr) : null,
        msrp: parsed.msrp != null ? Number(parsed.msrp) : null,
        title: parsed.title || originalItem.title || '',
        disclaimer: parsed.disclaimer || originalItem.disclaimer || '',
        expiration_date: parsed.expiration_date || null
      }
    }
  };
});
